// Uncached syscall mailbox: a 2KB scratch window of device storage in the
// upper half of the SimControl region. Device space carries the PMA device
// attribute on every engine, so no guest cache can hold a copy -- unlike the
// legacy RAM magicmem, which a private write-back L2 (ax66 PL2C) shadows.
// Layout: eight u64 arg/result slots at +0x0, payload data area after them.
// A write to SYSCALL_GO_OFFSET executes the staged syscall synchronously;
// the result replaces the syscall number in slot 0.
static constexpr uint64_t SYSCALL_GO_OFFSET = 0x28;
static constexpr uint64_t SYSCALL_WINDOW_OFFSET = 0x800;
static constexpr uint64_t SYSCALL_WINDOW_SIZE = 0x800;

