    qemu::LibQemu m_inst;
    QemuInstanceDmiManager m_dmi_mgr;
    TargetSignalSocket<bool> reset;

    cci::cci_param<std::string> p_tcg_mode;
    cci::cci_param<std::string> p_sync_policy;
    TcgMode m_tcg_mode;

    cci::cci_param<bool> p_icount;
    cci::cci_param<int> p_icount_mips;

    cci::cci_param<std::string> p_args;
    bool p_display_argument_set;

    cci::cci_param<std::string> p_accel;
    cci::cci_param<std::string> p_serial;
    cci::cci_param<int> p_num_cpus;

    /*
     * The instance asks the platform to end the run: a semihosting SYS_EXIT
     * (QEMU would exit() the process from the vCPU thread) or the QEMU main
     * loop returning on a host signal such as SIGTERM (QEMU would exit()
     * from the iothread). libqemu hands the status here instead and the
     * kernel thread stops the simulation the same way a StopperV2 write
     * does. sc_main reads guest_exit_status afterwards.
