#ifndef STOPPER_V2_H
#define STOPPER_V2_H

#include <systemc>
#include <tlm>
#include <tlm_utils/simple_target_socket.h>
#include <cci_configuration>
#include <scp/report.h>
#include <async_event.h>

class StopperV2 : public sc_core::sc_module {
public:
    SCP_LOGGER(());

    tlm_utils::simple_target_socket<StopperV2> target_socket;
    cci::cci_param<uint32_t> magic_value;
    /*
     * A guest that can only signal success has no way to report a failure: it
     * writes something the stopper ignores and then spins, which is
     * indistinguishable from a hang. Recognising a second value lets a failing
     * run end and say so.
     */
    cci::cci_param<uint32_t> fail_magic_value;
    /* Set when fail_magic_value is seen, so sc_main can pick it up. */
    cci::cci_param<bool> failed;

    StopperV2(const sc_core::sc_module_name& name);
    virtual ~StopperV2();

    void b_transport(tlm::tlm_generic_payload& trans, sc_core::sc_time& delay);
    void stop_proc();

private:
    gs::async_event m_stop_event;
    bool m_failed;
};

extern "C" void module_register();

#endif

########## stopper_v2.cc ##########
#include "stopper_v2.h"
#include <module_factory_registery.h>
#include <cciutils.h>
#include <scp/report.h>

StopperV2::StopperV2(const sc_core::sc_module_name& name)
    : sc_core::sc_module(name)
    , target_socket("target_socket")
    , magic_value("magic_value", 0x54495845) // Default to "EXIT" (little endian)
    /*
     * The demo apps write magic ^ 1 when their checks fail, so that is the
     * default. Set it equal to magic_value to disable the distinction.
     */
    , fail_magic_value("fail_magic_value", 0x54495844)
    , failed("failed", false)
    , m_stop_event(true)
    , m_failed(false)
{
    target_socket.register_b_transport(this, &StopperV2::b_transport);
    SC_HAS_PROCESS(StopperV2);
    SC_THREAD(stop_proc);
}

StopperV2::~StopperV2() {}

void StopperV2::stop_proc() {
    wait(m_stop_event);
    if (m_failed) {
        /*
         * Warning rather than SCP_ERR: SC_ERROR throws by default, which turns
         * a reported test failure into an abort and makes it look like a crash.
         * The result travels to sc_main through the "failed" parameter instead.
         */
        SCP_WARN(()) << "Failure value received. The guest reported that its "
                        "checks did not pass. Terminating simulation.";
    } else {
        SCP_INFO(()) << "Stop event received. Terminating simulation.";
    }
    sc_core::sc_stop();
}

void StopperV2::b_transport(tlm::tlm_generic_payload& trans, sc_core::sc_time& delay) {
    if (trans.get_command() == tlm::TLM_WRITE_COMMAND) {
        uint32_t data = 0;
        uint32_t len = trans.get_data_length();
        unsigned char* ptr = trans.get_data_ptr();

        if (len > 4) len = 4;
        memcpy(&data, ptr, len);

        if (data == magic_value.get_value()) {
            SCP_INFO(()) << "Magic value 0x" << std::hex << data << " received. Triggering async stop.";
            // gs::async_event handles the thread crossing and kernel wakeup internally
            m_stop_event.async_notify();
        } else if (data == fail_magic_value.get_value()) {
            SCP_WARN(()) << "Failure value 0x" << std::hex << data
                         << " received. Triggering async stop.";
            m_failed = true;
            failed.set_value(true);
            m_stop_event.async_notify();
        }
    }
    trans.set_response_status(tlm::TLM_OK_RESPONSE);
}

void module_register() {
    GSC_MODULE_REGISTER_C(StopperV2);
}
