########## mmio-bridge.h ##########
/*
 * mmio-bridge.h
 *
 * Copyright (c) 2026 Andes Technology Corp.
 *
 * QEMU-machine to SystemC bridge: maps an MMIO window of the QEMU system
 * address space onto a TLM initiator socket, so guests running on a real
 * qbox machine (e.g. -M andes_ae350 booting Linux) can reach SystemC-side
 * v2 models through the platform router. This is the hybrid-mode
 * counterpart of the -M none flow, where the QemuCpu socket owns the whole
 * address space; here the machine owns it and this bridge carves a window
 * out of it.
 *
 * The QEMU access callbacks run on a vCPU thread holding the BQL; the
 * transaction is handed to the SystemC thread (run_on_sysc) with the BQL
 * dropped for the duration, following the QemuInitiatorSocket convention.
 */

#ifndef _QEMU_COMPONENTS_MMIO_BRIDGE_H
#define _QEMU_COMPONENTS_MMIO_BRIDGE_H

#include <systemc>
#include <tlm>
#include <tlm_utils/simple_initiator_socket.h>

#include <cci_configuration>
#include <scp/report.h>

#include <libqemu-cxx/libqemu-cxx.h>
#include <module_factory_registery.h>
#include <qemu-instance.h>

#include <async_event.h>

class QemuMmioBridge : public sc_core::sc_module
{
    SCP_LOGGER();

public:
    tlm_utils::simple_initiator_socket<QemuMmioBridge> initiator_socket;
    cci::cci_param<uint64_t> p_mmio_base;
    cci::cci_param<uint64_t> p_mmio_size;
    cci::cci_param<uint64_t> p_tick_ns;

    QemuMmioBridge(const sc_core::sc_module_name& name, sc_core::sc_object* o)
        : QemuMmioBridge(name, [o]() -> QemuInstance& {
            QemuInstance* inst = dynamic_cast<QemuInstance*>(o);
            if (!inst) {
                SC_REPORT_FATAL("QemuMmioBridge", "args must name a QemuInstance");
            }
            return *inst;
        }())
    {
    }

    SC_HAS_PROCESS(QemuMmioBridge);
    QemuMmioBridge(const sc_core::sc_module_name& name, QemuInstance& inst)
        : sc_core::sc_module(name)
        , initiator_socket("initiator_socket")
        , p_mmio_base("mmio_base", 0, "Guest address of the bridged window")
        , p_mmio_size("mmio_size", 0, "Size of the bridged window")
        , p_tick_ns("tick_ns", 1000000,
                    "Heartbeat period. A machine-mode platform has no QemuCpu "
                    "quantum keeper, so without a timed event the SystemC "
                    "kernel parks in async_suspend -- where the 2.3.4 kernel "
                    "deadlocks against the cross-thread wakeup this bridge "
                    "needs. 0 disables.")
        , m_inst(inst)
        , m_on_sysc((const char*)name)
    {
        if (p_tick_ns.get_value() != 0) {
            m_tick_period = sc_core::sc_time((double)p_tick_ns.get_value(), sc_core::SC_NS);
            SC_THREAD(heartbeat);
        }
    }

    void before_end_of_elaboration() override
    {
        if (p_mmio_size.get_value() == 0) {
            SCP_FATAL(()) << "mmio_size must be set";
        }
        qemu::LibQemu& q = m_inst.get();

        m_ops = q.memory_region_ops_new();
        m_ops->set_read_callback([this](uint64_t addr, uint64_t* val, unsigned int size,
                                        qemu::MemoryRegionOps::MemTxAttrs attrs) {
            return access(tlm::TLM_READ_COMMAND, addr, reinterpret_cast<uint8_t*>(val), size);
        });
        m_ops->set_write_callback([this](uint64_t addr, uint64_t val, unsigned int size,
                                         qemu::MemoryRegionOps::MemTxAttrs attrs) {
            return access(tlm::TLM_WRITE_COMMAND, addr, reinterpret_cast<uint8_t*>(&val), size);
        });
        m_ops->set_max_access_size(8);
        /* Wide accesses (an ACE port transfer can be up to 512 bytes) go
         * through the ex callbacks as a single beat -- the qbox flatview
         * ex path forwards any >8-byte access to a region that provides
         * them -- instead of being split into <=8-byte beats. */
        m_ops->set_read_ex_callback([this](uint64_t addr, uint8_t* data, unsigned int size) {
            return access(tlm::TLM_READ_COMMAND, addr, data, size);
        });
        m_ops->set_write_ex_callback([this](uint64_t addr, uint8_t* data, unsigned int size) {
            return access(tlm::TLM_WRITE_COMMAND, addr, data, size);
        });

        m_mr.reset(new qemu::MemoryRegion(q.object_new<qemu::MemoryRegion>()));
        m_mr->init_io(qemu::Object(), "systemc-mmio-bridge", p_mmio_size.get_value(), m_ops);
        /* Mapping happens on the heartbeat's first activation: at
         * before_end_of_elaboration the machine (and the final
         * system_memory contents) do not exist yet -- a region added here
         * silently ends up outside the machine's tree. */
    }

private:
    void heartbeat()
    {
        /* First activation runs after every start_of_simulation callback,
         * i.e. after finish_qemu_init created the machine: mount the
         * bridge window now. */
        std::shared_ptr<qemu::MemoryRegion> sysmem = m_inst.get().get_system_memory();
        sysmem->add_subregion(*m_mr, p_mmio_base.get_value());
        SCP_WARN(()) << "bridged [0x" << std::hex << p_mmio_base.get_value() << ", +0x"
                     << p_mmio_size.get_value() << ") into SystemC";

        /* CCI forbids global-broker lookups from inside the SystemC
         * hierarchy, so the period is latched at construction. */
        const sc_core::sc_time period = m_tick_period;
        for (;;) {
            sc_core::wait(period);
        }
    }

    qemu::MemoryRegionOps::MemTxResult access(tlm::tlm_command cmd, uint64_t addr, uint8_t* data,
                                              unsigned int size)
    {
        tlm::tlm_generic_payload trans;
        trans.set_command(cmd);
        trans.set_address(p_mmio_base.get_value() + addr);
        trans.set_data_ptr(data);
        trans.set_data_length(size);
        trans.set_streaming_width(size);
        trans.set_byte_enable_ptr(nullptr);
        trans.set_dmi_allowed(false);
        trans.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);

        /* vCPU thread holds the BQL; drop it while SystemC services us. */
        const bool bql = m_inst.get().iothread_locked();
        if (bql) m_inst.get().unlock_iothread();
        m_on_sysc.run_on_sysc([this, &trans] {
            sc_core::sc_time t = sc_core::SC_ZERO_TIME;
            initiator_socket->b_transport(trans, t);
        });
        if (bql) m_inst.get().lock_iothread();

        return trans.get_response_status() == tlm::TLM_OK_RESPONSE
                   ? qemu::MemoryRegionOps::MemTxOK
                   : qemu::MemoryRegionOps::MemTxDecodeError;
    }

    QemuInstance& m_inst;
    sc_core::sc_time m_tick_period;
    gs::runonsysc m_on_sysc;
    qemu::MemoryRegionOpsPtr m_ops;
    std::shared_ptr<qemu::MemoryRegion> m_mr;
};

#endif
